/* Answer key grid */
.keytable { border:2px solid var(--navy); }
.keytable th, .keytable td {
  text-align:center; padding:6px 3px; font-size:1.1rem; border:1px solid #CBD5E1;
}
.krow-q th { background: var(--navy); color:#fff; }
.krow-a td { background:#fff; font-weight:bold; color:var(--green); }
.keyfix { color: var(--red-bd); }
